7|
8|    /* Avoid timeout with long inputs */
9|    if(size > (64 * 1024)) return 0;
10|
11|    if(data[size-1] != '\0') return 0;
12|
13|    const uint8_t* ptr = data;
14|    utf8proc_int32_t c = 0, c_prev = 0, state = 0;
15|    unsigned int options;
16|    utf8proc_ssize_t ret, bytes = 0;
17|    utf8proc_uint8_t *str = NULL;
18|    size_t len = strlen((const char*)data);
19|
20|    while(bytes != len)
21|    {
22|        ret = utf8proc_iterate(ptr, -1, &c);
23|
24|        if(ret < 0 || ret == 0) break;
25|
26|        bytes += ret;
27|        ptr += ret;
28|
29|        utf8proc_tolower(c);
30|        utf8proc_toupper(c);
31|        utf8proc_totitle(c);
