41|
42|        c_prev = c;
43|    }
44|
45|    utf8proc_int32_t *copy = size >= 4 ? malloc(size) : NULL;
46|
47|    if(copy)
48|    {
49|        size /= 4; /* number of utf8proc_int32_t code points that fit in copy */
50|
51|        options = UTF8PROC_STRIPCC | UTF8PROC_NLF2LS | UTF8PROC_NLF2PS;
52|        memcpy(copy, data, size * sizeof(utf8proc_int32_t));
53|        utf8proc_normalize_utf32(copy, size, options);
