57|        utf8proc_normalize_utf32(copy, size, options);
58|
59|        options = UTF8PROC_STRIPCC | UTF8PROC_NLF2PS;
60|        memcpy(copy, data, size * sizeof(utf8proc_int32_t));
61|        utf8proc_normalize_utf32(copy, size, options);
62|
63|        options = UTF8PROC_STRIPCC;
64|        memcpy(copy, data, size * sizeof(utf8proc_int32_t));
65|        utf8proc_normalize_utf32(copy, size, options);
66|
67|        options = UTF8PROC_LUMP;
68|        memcpy(copy, data, size * sizeof(utf8proc_int32_t));
69|        utf8proc_normalize_utf32(copy, size, options);
70|
71|        options = 0;
72|        memcpy(copy, data, size * sizeof(utf8proc_int32_t));
73|        utf8proc_normalize_utf32(copy, size, options);
74|
75|        free(copy);
76|    }
