78|    utf8proc_free(utf8proc_NFD(data));
79|    utf8proc_free(utf8proc_NFC(data));
80|    utf8proc_free(utf8proc_NFKD(data));
81|    utf8proc_free(utf8proc_NFKC(data));
82|    utf8proc_free(utf8proc_NFKC_Casefold(data));
