617|UTF8PROC_DLLEXPORT utf8proc_ssize_t utf8proc_normalize_utf32(utf8proc_int32_t *buffer, utf8proc_ssize_t length, unsigned int options) {
618|  /* UTF8PROC_NULLTERM option will be ignored, 'length' is never ignored */
619|  if (options & (UTF8PROC_NLF2LS | UTF8PROC_NLF2PS | UTF8PROC_STRIPCC)) {
620|    utf8proc_ssize_t rpos;
621|    utf8proc_ssize_t wpos = 0;
622|    utf8proc_int32_t uc;
623|    for (rpos = 0; rpos < length; rpos++) {
624|      uc = buffer[rpos];
625|      if (uc == 0x000D && rpos < length-1 && buffer[rpos+1] == 0x000A) rpos++;
626|      if (uc == 0x000A || uc == 0x000D || uc == 0x0085 ||
627|          ((options & UTF8PROC_STRIPCC) && (uc == 0x000B || uc == 0x000C))) {
628|        if (options & UTF8PROC_NLF2LS) {
629|          if (options & UTF8PROC_NLF2PS) {
630|            buffer[wpos++] = 0x000A;
631|          } else {
632|            buffer[wpos++] = 0x2028;
633|          }
634|        } else {
635|          if (options & UTF8PROC_NLF2PS) {
636|            buffer[wpos++] = 0x2029;
637|          } else {
638|            buffer[wpos++] = 0x0020;
639|          }
640|        }
641|      } else if ((options & UTF8PROC_STRIPCC) &&
642|          /* uc < 0 is a grapheme-break sentinel from UTF8PROC_CHARBOUND,
643|             not a control character, so keep it */
644|          ((uc >= 0 && uc < 0x0020) || (uc >= 0x007F && uc < 0x00A0))) {
645|        if (uc == 0x0009) buffer[wpos++] = 0x0020;
646|        /* a removed control character is a grapheme of its own, so also
647|           drop the boundary sentinel that UTF8PROC_CHARBOUND put before it */
648|        else if ((options & UTF8PROC_CHARBOUND) && wpos > 0 && buffer[wpos-1] == -1) wpos--;
649|      } else {
650|        buffer[wpos++] = uc;
651|      }
652|    }
653|    length = wpos;
654|  }
655|  if (options & UTF8PROC_COMPOSE) {
656|    utf8proc_int32_t *starter = NULL;
657|    const utf8proc_property_t *starter_property = NULL;
658|    utf8proc_propval_t max_combining_class = -1;
659|    utf8proc_ssize_t rpos;
660|    utf8proc_ssize_t wpos = 0;
661|    for (rpos = 0; rpos < length; rpos++) {
662|      utf8proc_int32_t current_char = buffer[rpos];
663|      if (current_char < 0 || current_char >= 0x110000) {
664|        /* grapheme-break sentinel or out-of-range codepoint: pass it through
665|           unchanged, but never compose across it, since we cannot inspect it
666|           (unsafe_get_property would OOB on utf8proc_stage1table, idx = uc >> 8).
667|           utf8proc_reencode drops what cannot be encoded, so this is invisible
668|           to utf8proc_map. */
669|        buffer[wpos++] = current_char;
670|        starter = NULL;
671|        starter_property = NULL;
672|        max_combining_class = -1;
673|        continue;
674|      }
675|      const utf8proc_property_t *current_property = unsafe_get_property(current_char);
676|      if (starter && current_property->combining_class > max_combining_class) {
677|        /* combination perhaps possible */
678|        utf8proc_int32_t hangul_lindex;
679|        utf8proc_int32_t hangul_sindex;
680|        hangul_lindex = *starter - UTF8PROC_HANGUL_LBASE;
681|        if (hangul_lindex >= 0 && hangul_lindex < UTF8PROC_HANGUL_LCOUNT) {
682|          utf8proc_int32_t hangul_vindex;
683|          hangul_vindex = current_char - UTF8PROC_HANGUL_VBASE;
684|          if (hangul_vindex >= 0 && hangul_vindex < UTF8PROC_HANGUL_VCOUNT) {
685|            *starter = UTF8PROC_HANGUL_SBASE +
686|              (hangul_lindex * UTF8PROC_HANGUL_VCOUNT + hangul_vindex) *
687|              UTF8PROC_HANGUL_TCOUNT;
688|            starter_property = NULL;
689|            continue;
690|          }
691|        }
692|        hangul_sindex = *starter - UTF8PROC_HANGUL_SBASE;
693|        if (hangul_sindex >= 0 && hangul_sindex < UTF8PROC_HANGUL_SCOUNT &&
694|            (hangul_sindex % UTF8PROC_HANGUL_TCOUNT) == 0) {
695|          utf8proc_int32_t hangul_tindex;
696|          hangul_tindex = current_char - UTF8PROC_HANGUL_TBASE;
697|          if (hangul_tindex > 0 && hangul_tindex < UTF8PROC_HANGUL_TCOUNT) {
698|            *starter += hangul_tindex;
699|            starter_property = NULL;
700|            continue;
701|          }
702|        }
703|        if (!starter_property) {
704|          /* `*starter` is either a Hangul character, or points into
705|             the table `utf8proc_combinations_combined`. It is always
706|             valid. */
707|          starter_property = unsafe_get_property(*starter);
708|        }
709|        int idx = starter_property->comb_index;
710|        if (idx < 0x3FF && current_property->comb_issecond) {
711|          int len = starter_property->comb_length;
712|          utf8proc_int32_t max_second = utf8proc_combinations_second[idx + len - 1];
713|          if (current_char <= max_second) {
714|            int off;
715|            // TODO: binary search? arithmetic search?
716|            for (off = 0; off < len; ++off) {
717|              utf8proc_int32_t second = utf8proc_combinations_second[idx + off];
718|              if (current_char < second) {
719|                /* not found */
720|                break;
721|              }
722|              if (current_char == second) {
723|                /* found */
724|                utf8proc_int32_t composition = utf8proc_combinations_combined[idx + off];
725|                *starter = composition;
726|                starter_property = NULL;
727|                break;
728|              }
729|            }
730|            if (starter_property == NULL) {
731|              /* found */
732|              continue;
733|            }
734|          }
735|        }
736|      }
737|      buffer[wpos] = current_char;
738|      if (current_property->combining_class) {
739|        if (current_property->combining_class > max_combining_class) {
740|          max_combining_class = current_property->combining_class;
741|        }
742|      } else {
743|        starter = buffer + wpos;
744|        starter_property = NULL;
745|        max_combining_class = -1;
746|      }
747|      wpos++;
748|    }
749|    length = wpos;
750|  }
751|  return length;
752|}

