291|static utf8proc_bool grapheme_break_extended(int lbc, int tbc, int licb, int ticb, utf8proc_int32_t *state)
292|{
293|  if (state) {
294|    int state_bc, state_icb; /* boundclass and indic_conjunct_break state */
295|    if (*state == 0) { /* state initialization */
296|      state_bc = lbc;
297|      state_icb = licb;
298|    }
299|    else { /* lbc and licb are already encoded in *state */
300|      state_bc = *state & 0xff;  // 1st byte of state is bound class
301|      state_icb = *state >> 8;   // 2nd byte of state is indic conjunct break
302|    }
303|
304|    utf8proc_bool break_permitted = grapheme_break_simple(state_bc, tbc) &&
305|       !(state_icb == UTF8PROC_INDIC_CONJUNCT_BREAK_LINKER
306|        && ticb == UTF8PROC_INDIC_CONJUNCT_BREAK_CONSONANT); // GB9c
307|
308|    // Special support for GB9c.  Don't break between linker + 0+ extend chars and consonant.
309|    // We enter LINKER state after a linker and stay in it for extend chars.
310|    state_icb = (state_icb == UTF8PROC_INDIC_CONJUNCT_BREAK_LINKER && ticb == UTF8PROC_INDIC_CONJUNCT_BREAK_EXTEND) ? state_icb : ticb;
311|
312|    // Special support for GB 12/13 made possible by GB999. After two RI
313|    // class codepoints we want to force a break. Do this by resetting the
314|    // second RI's bound class to UTF8PROC_BOUNDCLASS_OTHER, to force a break
315|    // after that character according to GB999 (unless of course such a break is
316|    // forbidden by a different rule such as GB9).
317|    if (state_bc == tbc && tbc == UTF8PROC_BOUNDCLASS_REGIONAL_INDICATOR)
318|      state_bc = UTF8PROC_BOUNDCLASS_OTHER;
319|    // Special support for GB11 (emoji extend* zwj / emoji)
320|    else if (state_bc == UTF8PROC_BOUNDCLASS_EXTENDED_PICTOGRAPHIC) {
321|      if (tbc == UTF8PROC_BOUNDCLASS_EXTEND) // fold EXTEND codepoints into emoji
322|        state_bc = UTF8PROC_BOUNDCLASS_EXTENDED_PICTOGRAPHIC;
323|      else if (tbc == UTF8PROC_BOUNDCLASS_ZWJ)
324|        state_bc = UTF8PROC_BOUNDCLASS_E_ZWG; // state to record emoji+zwg combo
325|      else
326|        state_bc = tbc;
327|    }
328|    else
329|      state_bc = tbc;
330|
331|    *state = state_bc + (state_icb << 8);
332|    return break_permitted;
333|  }
334|  else
335|    return grapheme_break_simple(lbc, tbc);
336|}

